// Perfil desde PostgreSQL via /api/profiles/runtime. Un item por feed, igual
// que antes: el primero es la busqueda de Google News del propio usuario.
const p = $('Perfil (API)').first().json.profile || {};
const profile = {
  idioma: p.idioma || 'es',
  tono: p.tono || 'Profesional, claro y cercano.',
  temas: p.temas || '',
  categorias: Array.isArray(p.categorias) ? p.categorias : [],
};
const feeds = Array.isArray(p.feeds) && p.feeds.length ? p.feeds : [p.feed_url].filter(Boolean);
return feeds.map((feed_url) => ({ json: { profile, feed_url } }));

const title = ($json.title || '').trim();
const link = $json.link || $json.guid || '';
const norm = title.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]/g, '').trim();
return { json: {
  title,
  link,
  item_key: 'brand:' + norm,
  text: (title + ' ' + ($json.contentSnippet || $json.content || '')).slice(0, 1800),
} };

const store = $getWorkflowStaticData('global');
const seen = store.brandSeen || {};
const now = Date.now();
const TTL = 45 * 24 * 60 * 60 * 1000;
for (const k of Object.keys(seen)) { if (now - seen[k] > TTL) delete seen[k]; }
const out = [];
for (const item of $input.all()) {
  const key = item.json.item_key;
  if (!key || key === 'brand:' || seen[key]) continue;
  seen[key] = now;
  out.push({ json: item.json, pairedItem: item.pairedItem });
}
store.brandSeen = seen;
return out;

