// Lee la respuesta del Automation Center (/api/ai/generate).
// `data` ya viene parseado; `text` es el respaldo. Se acepta ademas el sobre
// antiguo de Gemini para que una importacion a medias no falle en silencio.
function leerIA(r) {
  if (!r) return null;
  if (r.data && typeof r.data === 'object') return r.data;
  const crudo = typeof r.text === 'string'
    ? r.text
    : (r.candidates && r.candidates[0] && r.candidates[0].content
       && r.candidates[0].content.parts && r.candidates[0].content.parts[0]
       && r.candidates[0].content.parts[0].text);
  if (!crudo) return null;
  return JSON.parse(String(crudo).replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, ''));
}

// Parsea la respuesta del Automation Center, guarda el borrador como .md
// y devuelve los metadatos para el aviso.
// El ENLACE se toma del nodo de normalización, no de la IA.
const fs = require('fs');
const DIR = '/files/output/marca-personal';
try { fs.mkdirSync(DIR, { recursive: true }); } catch (e) {}

let data;
try {
  data = leerIA($json);
} catch (e) {
  throw new Error('La respuesta de la IA no es JSON válido: ' + e.message);
}
if (!data || !data.titulo || !data.borrador_linkedin) {
  throw new Error('Borrador incompleto: la IA no devolvió titulo o texto');
}

let fuente = '';
try { fuente = $('Normalizar fuente').item.json.link || ''; } catch (e) {}

const tags = Array.isArray(data.hashtags) ? data.hashtags.join(' ') : String(data.hashtags || '');
const fecha = new Date().toISOString().slice(0, 10);
const slug = String(data.titulo).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'borrador';
const ruta = DIR + '/' + fecha + '_' + slug + '.md';

const md = '# ' + data.titulo + '\n\n'
  + '> Borrador generado el ' + fecha + '. Revísalo antes de publicar.\n\n'
  + data.borrador_linkedin + '\n\n'
  + (tags ? tags + '\n\n' : '')
  + (fuente ? 'Fuente: ' + fuente + '\n' : '');

try { fs.writeFileSync(ruta, md, 'utf8'); } catch (e) { throw new Error('No se pudo escribir ' + ruta + ': ' + e.message); }

return { json: {
  titulo: data.titulo,
  ruta,
  preview: data.borrador_linkedin.slice(0, 240),
  fuente,
} };

// Un único mensaje-resumen con todos los borradores generados en esta ejecución.
const items = $input.all().map((i) => i.json);
if (items.length === 0) return [];

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fecha = new Date().toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' });

const bloques = items.map((b, i) =>
  `<b>${i + 1}. ${esc(b.titulo)}</b>\n${esc(b.preview)}…\n📄 <code>${esc(b.ruta)}</code>`
).join('\n\n━━━━━━━━━━\n\n');

const texto =
  `✍️ <b>BORRADORES LINKEDIN</b>\n<i>${fecha}</i>\n\n` +
  `━━━━━━━━━━\n\n${bloques}\n\n━━━━━━━━━━\n` +
  `<i>${items.length} borrador(es) en output/marca-personal/</i>`;

return [{ json: { texto } }];

